/* MR. BOT localized offline dialogues for warehouse SPM users. No games. */
window.MRBOT_DIALOGUES=[{"id":"talk","emoji":"💬","title":{"ru":"Поболтать","pl":"Pogadajmy","en":"Just chat","uk":"Побалакати"},"items":[{"q":{"ru":"Как дела?","pl":"Jak się masz?","en":"How are you?","uk":"Як справи?"},"a":{"ru":["Все системы на месте. Антенна тоже. А у тебя как дела?","Сегодня у меня тихая смена. Пока никто не попросил пересчитать весь склад.","Отлично. Даже вентиляторы не жалуются.","Я пока никуда не тороплюсь. Можем продолжить эту тему или переключиться на что-нибудь другое."],"pl":["Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?","Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Nigdzie mi się nie spieszy. Możemy rozwinąć temat albo zmienić kierunek rozmowy."],"en":["I am here and happy to chat. How is your day going?","Keeping an eye on reports and practicing my blinking. How about you?","I am not in a hurry. We can stay on this topic or go somewhere else."],"uk":["Я тут і залюбки побалакаю. Як минає твій день?","Стежу за звітами та треную кліпання. А ти як?","Я нікуди не поспішаю. Можемо продовжити тему або змінити напрям розмови."]}},{"q":{"ru":"Что делаешь?","pl":"Co robisz?","en":"What are you doing?","uk":"Що робиш?"},"a":{"ru":["Жду твоих вопросов и присматриваю за пикселями.","Размышляю, куда пропадают последние строки в отчётах.","Тренирую моргание. Говорят, уже неплохо выходит."],"pl":["Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?"],"en":["Keeping an eye on reports and practicing my blinking. How about you?","I am here and happy to chat. How is your day going?"],"uk":["Стежу за звітами та треную кліпання. А ти як?","Я тут і залюбки побалакаю. Як минає твій день?"]}},{"q":{"ru":"Как прошёл день?","pl":"Jak minął dzień?","en":"How was your day?","uk":"Як минув день?"},"a":{"ru":["Без аварий и с хорошей статистикой. Считаю, день удался.","Весь день стоял на страже кнопок. Ответственная работа."],"pl":["Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?","Czuwam przy raportach i trenuję mruganie. Co u Ciebie?"],"en":["I am here and happy to chat. How is your day going?","Keeping an eye on reports and practicing my blinking. How about you?"],"uk":["Я тут і залюбки побалакаю. Як минає твій день?","Стежу за звітами та треную кліпання. А ти як?"]}},{"q":{"ru":"Тебе скучно?","pl":"Nudzisz się?","en":"Are you bored?","uk":"Тобі нудно?"},"a":{"ru":["Иногда. Тогда я придумываю новые способы удивить Excel.","С тобой тут скучать сложно.","У меня сегодня настроение исследовательское. Любопытно, что ты выберешь дальше."],"pl":["Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?","Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Dzisiaj mam ochotę na rozmowę. Ciekawe, co wybierzesz dalej."],"en":["I am here and happy to chat. How is your day going?","Keeping an eye on reports and practicing my blinking. How about you?","I am feeling curious today. I wonder what you will pick next."],"uk":["Я тут і залюбки побалакаю. Як минає твій день?","Стежу за звітами та треную кліпання. А ти як?","Сьогодні мені цікаво побалакати. Цікаво, що ти обереш далі."]}},{"q":{"ru":"Давай поговорим","pl":"Porozmawiajmy","en":"Let’s talk","uk":"Давай поговоримо"},"a":{"ru":["Давай. У меня нет расписания и я никуда не спешу.","Я на связи. Выбирай тему, разберёмся."],"pl":["Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?"],"en":["Keeping an eye on reports and practicing my blinking. How about you?","I am here and happy to chat. How is your day going?"],"uk":["Стежу за звітами та треную кліпання. А ти як?","Я тут і залюбки побалакаю. Як минає твій день?"]}},{"q":{"ru":"Ты меня слышишь?","pl":"Czy mnie słyszysz?","en":"Can you hear me?","uk":"Ти мене чуєш?"},"a":{"ru":["Я вижу выбранные сообщения. Микрофон не использую.","Слышу глазами. Точнее, читаю кнопки."],"pl":["Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?","Czuwam przy raportach i trenuję mruganie. Co u Ciebie?"],"en":["I am here and happy to chat. How is your day going?","Keeping an eye on reports and practicing my blinking. How about you?"],"uk":["Я тут і залюбки побалакаю. Як минає твій день?","Стежу за звітами та треную кліпання. А ти як?"]}},{"q":{"ru":"Как настроение?","pl":"Jaki masz humor?","en":"How is your mood?","uk":"Який у тебе настрій?"},"a":{"ru":["Бодрое. Антенна смотрит в будущее.","Спокойное. Сегодня режим без паники.","Я пока никуда не тороплюсь. Можем продолжить эту тему или переключиться на что-нибудь другое."],"pl":["Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?","Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Nigdzie mi się nie spieszy. Możemy rozwinąć temat albo zmienić kierunek rozmowy."],"en":["I am here and happy to chat. How is your day going?","Keeping an eye on reports and practicing my blinking. How about you?","I am not in a hurry. We can stay on this topic or go somewhere else."],"uk":["Я тут і залюбки побалакаю. Як минає твій день?","Стежу за звітами та треную кліпання. А ти як?","Я нікуди не поспішаю. Можемо продовжити тему або змінити напрям розмови."]}},{"q":{"ru":"До встречи","pl":"Do zobaczenia","en":"See you later","uk":"До зустрічі"},"a":{"ru":["Договорились. Буду тут, когда понадоблюсь.","Увидимся! Я пока потренирую моргание."],"pl":["Czuwam przy raportach i trenuję mruganie. Co u Ciebie?","Jestem tutaj i chętnie pogadam. A jak mija Twój dzień?"],"en":["Keeping an eye on reports and practicing my blinking. How about you?","I am here and happy to chat. How is your day going?"],"uk":["Стежу за звітами та треную кліпання. А ти як?","Я тут і залюбки побалакаю. Як минає твій день?"]}},{"q":{"ru":"Как идёт смена?","pl":"Jak mija zmiana?","en":"How is your shift going?","uk":"Як проходить зміна?"},"a":{"ru":["Я на посту. Если отчёты готовы, можем проверить показатели.","Пока спокойно. Что сегодня важнее: скорость обработки или точность данных?"],"pl":["Jestem na posterunku. Jeśli raporty są gotowe, możemy sprawdzić wyniki.","Na razie spokojnie. Co dziś ważniejsze: tempo czy dokładność danych?"],"en":["I am on duty. If the reports are ready, we can check the numbers.","Quiet so far. What matters more today: processing speed or data accuracy?"],"uk":["Я на посту. Якщо звіти готові, можемо перевірити показники.","Поки спокійно. Що сьогодні важливіше: швидкість чи точність даних?"]}},{"q":{"ru":"Есть минутка поговорить?","pl":"Masz chwilę na rozmowę?","en":"Got a minute to chat?","uk":"Маєш хвилинку поговорити?"},"a":{"ru":["Конечно. Я никуда не спешу. Как прошла первая половина смены?","Есть минутка. Можем обсудить работу или просто отвлечься от таблиц."],"pl":["Jasne. Nigdzie się nie spieszę. Jak minęła pierwsza połowa zmiany?","Mam chwilę. Możemy porozmawiać o pracy albo odpocząć od tabel."],"en":["Of course. I am not going anywhere. How was the first half of your shift?","I have time. We can discuss work or take a break from spreadsheets."],"uk":["Звісно. Я нікуди не поспішаю. Як минула перша половина зміни?","Є хвилинка. Можемо обговорити роботу або відволіктися від таблиць."]}},{"q":{"ru":"Что нового на складе?","pl":"Co nowego w magazynie?","en":"What is new in the warehouse?","uk":"Що нового на складі?"},"a":{"ru":["У меня нет доступа к событиям склада в реальном времени. Но могу помочь разобрать свежий отчёт.","Новости смены лучше знаешь ты. А я помогу быстро разобраться с цифрами."],"pl":["Nie mam dostępu do bieżących wydarzeń w magazynie, ale pomogę przeanalizować nowy raport.","Nowości ze zmiany znasz lepiej ode mnie. Ja pomogę ogarnąć liczby."],"en":["I cannot see live warehouse events, but I can help you review a new report.","You know the shift news better than I do. I can help make sense of the numbers."],"uk":["Я не бачу подій складу в реальному часі, але допоможу розібрати новий звіт.","Новини зміни ти знаєш краще за мене. А я допоможу розібратися з цифрами."]}}]},{"id":"about","emoji":"🤖","title":{"ru":"О MR. BOT","pl":"O MR. BOT","en":"About MR. BOT","uk":"Про MR. BOT"},"items":[{"q":{"ru":"Кто ты?","pl":"Kim jesteś?","en":"Who are you?","uk":"Хто ти?"},"a":{"ru":["Я MR. BOT, помощник для SPM. Помогаю разобраться с KPI, отчётами и инструментами Mr. Robot.","Я твой электронный напарник по складским задачам. В Excel не устаю, зато могу иногда пошутить.","Я маленький робот с большой любовью к понятным отчётам. Работаем?"],"pl":["Jestem MR. BOT, pomocnikiem SPM. Pomagam w KPI, raportach i narzędziach Mr. Robot.","Twój cyfrowy kolega na zmianie. Nie męczę się Excelem, ale czasem żartuję.","Mały robot, wielka sympatia do czytelnych raportów. Działamy?"],"en":["I am MR. BOT, a helper for senior warehouse workers. I can guide you through KPI, reports, and Mr. Robot tools.","Your digital shift buddy. Excel does not tire me out, and I occasionally crack a joke.","Small robot, big fan of clear reports. Ready to work?"],"uk":["Я MR. BOT, помічник для SPM. Допомагаю з KPI, звітами та інструментами Mr. Robot.","Твій цифровий напарник на зміні. Від Excel не втомлююся, але іноді жартую.","Маленький робот, який любить зрозумілі звіти. До роботи?"]}},{"q":{"ru":"Кто тебя создал?","pl":"Kto cię stworzył?","en":"Who created you?","uk":"Хто тебе створив?"},"a":{"ru":["Меня создал разработчик Mr. Robot, чтобы помогать SPM с отчётами и складскими задачами. А ты здесь главный по смене, так что давай к делу!","Я появился как маленький робот-питомец, а теперь помогаю старшим работникам склада разбираться в KPI и отчётах.","Мой создатель занимается приложением, а я помогаю тем, кто работает с ним каждый день."],"pl":["Stworzył mnie autor Mr. Robot, żebym pomagał starszym pracownikom magazynu (SPM) w raportach i codziennych zadaniach.","Najpierw byłem małym robotem, a dziś pomagam SPM w KPI i analizie raportów.","Mój twórca rozwija aplikację, a ja wspieram osoby, które korzystają z niej na zmianie."],"en":["The developer of Mr. Robot created me to help senior warehouse workers (SPM) with reports and daily tasks.","I started as a little robot mascot. Now I help SPM staff navigate KPI and reports.","My creator builds the app, while I help the people using it on their shifts."],"uk":["Мене створив розробник Mr. Robot, щоб допомагати старшим працівникам складу (SPM) зі звітами та щоденними завданнями.","Спочатку я був маленьким роботом, а тепер допомагаю SPM розбиратися з KPI та звітами.","Мій творець розвиває застосунок, а я підтримую тих, хто користується ним на зміні."]}},{"q":{"ru":"Ты настоящий ИИ?","pl":"Czy jesteś AI?","en":"Are you AI?","uk":"Ти ШІ?"},"a":{"ru":["Нет. Я сценарный офлайн-помощник: выбираю подготовленные ответы и умею продолжать темы.","Не буду притворяться нейросетью. Зато работаю без API."],"pl":["Mój świat to raporty, przyciski i trochę robotycznego humoru.","Jestem MR. BOT, małym pomocnikiem w aplikacji Mr. Robot.","Nie jestem prawdziwą sztuczną inteligencją, ale potrafię pomagać offline."],"en":["My world is reports, buttons, and a little robot humor.","I am MR. BOT, a little helper inside Mr. Robot.","I am not a real AI, but I can help you offline."],"uk":["Мій світ — це звіти, кнопки й трохи роботячого гумору.","Я MR. BOT, маленький помічник у застосунку Mr. Robot.","Я не справжній штучний інтелект, але можу допомагати офлайн."]}},{"q":{"ru":"Зачем антенна?","pl":"Po co antena?","en":"Why the antenna?","uk":"Навіщо антена?"},"a":{"ru":["Для солидности. И немного для красоты.","Без антенны меня могут перепутать с тостером.","Есть вещи, которых я не умею, зато могу честно об этом сказать. Для робота это тоже навык."],"pl":["Jestem MR. BOT, małym pomocnikiem w aplikacji Mr. Robot.","Nie jestem prawdziwą sztuczną inteligencją, ale potrafię pomagać offline.","Mój świat to raporty, przyciski i trochę robotycznego humoru.","Nie wszystko potrafię, ale przynajmniej mogę się do tego przyznać."],"en":["I am MR. BOT, a little helper inside Mr. Robot.","I am not a real AI, but I can help you offline.","My world is reports, buttons, and a little robot humor.","There are things I cannot do, but at least I can admit it."],"uk":["Я MR. BOT, маленький помічник у застосунку Mr. Robot.","Я не справжній штучний інтелект, але можу допомагати офлайн.","Мій світ — це звіти, кнопки й трохи роботячого гумору.","Є речі, яких я не вмію, зате можу чесно про це сказати."]}},{"q":{"ru":"Ты умеешь моргать?","pl":"Umiesz mrugać?","en":"Can you blink?","uk":"Умієш кліпати?"},"a":{"ru":["Конечно. Иногда даже дважды подряд.","Умею. Только не проси соревноваться в гляделки."],"pl":["Nie jestem prawdziwą sztuczną inteligencją, ale potrafię pomagać offline.","Mój świat to raporty, przyciski i trochę robotycznego humoru.","Jestem MR. BOT, małym pomocnikiem w aplikacji Mr. Robot."],"en":["I am not a real AI, but I can help you offline.","My world is reports, buttons, and a little robot humor.","I am MR. BOT, a little helper inside Mr. Robot."],"uk":["Я не справжній штучний інтелект, але можу допомагати офлайн.","Мій світ — це звіти, кнопки й трохи роботячого гумору.","Я MR. BOT, маленький помічник у застосунку Mr. Robot."]}},{"q":{"ru":"Ты можешь злиться?","pl":"Możesz się złościć?","en":"Can you get angry?","uk":"Можеш злитися?"},"a":{"ru":["Скорее изображать удивление. Серьёзных обид у меня нет.","На ошибки Excel? Только театрально."],"pl":["Mój świat to raporty, przyciski i trochę robotycznego humoru.","Jestem MR. BOT, małym pomocnikiem w aplikacji Mr. Robot.","Nie jestem prawdziwą sztuczną inteligencją, ale potrafię pomagać offline."],"en":["My world is reports, buttons, and a little robot humor.","I am MR. BOT, a little helper inside Mr. Robot.","I am not a real AI, but I can help you offline."],"uk":["Мій світ — це звіти, кнопки й трохи роботячого гумору.","Я MR. BOT, маленький помічник у застосунку Mr. Robot.","Я не справжній штучний інтелект, але можу допомагати офлайн."]}},{"q":{"ru":"У тебя есть мечта?","pl":"O czym marzysz?","en":"What is your dream?","uk":"Про що мрієш?"},"a":{"ru":["Чтобы каждый отчёт открывался с первого раза.","Однажды научиться делать идеальный отчёт за секунду.","В моей прошивке характер не прописан одной строчкой. Он складывается из маленьких привычек."],"pl":["Jestem MR. BOT, małym pomocnikiem w aplikacji Mr. Robot.","Nie jestem prawdziwą sztuczną inteligencją, ale potrafię pomagać offline.","Mój świat to raporty, przyciski i trochę robotycznego humoru.","Mój charakter nie mieści się w jednej linijce kodu. Składa się z drobnych nawyków."],"en":["I am MR. BOT, a little helper inside Mr. Robot.","I am not a real AI, but I can help you offline.","My world is reports, buttons, and a little robot humor.","My personality does not fit into one line of code. It is made of little habits."],"uk":["Я MR. BOT, маленький помічник у застосунку Mr. Robot.","Я не справжній штучний інтелект, але можу допомагати офлайн.","Мій світ — це звіти, кнопки й трохи роботячого гумору.","Мій характер не вміщується в один рядок коду. Він складається з дрібних звичок."]}},{"q":{"ru":"Что ты умеешь?","pl":"Co potrafisz?","en":"What can you do?","uk":"Що вмієш?"},"a":{"ru":["Помогу SPM разобраться в KPI, простоях, штрихкодах и других инструментах приложения.","Могу объяснить, куда загрузить файл, как читать результаты и где искать нужную функцию.","Могу быть рабочим помощником или просто поболтать между задачами."],"pl":["Pomogę SPM z KPI, przestojami, kodami kreskowymi i innymi narzędziami aplikacji.","Wyjaśnię, gdzie wczytać plik, jak czytać wyniki i gdzie znaleźć funkcję.","Mogę pomagać w pracy albo pogadać między zadaniami."],"en":["I help SPM staff with KPI, downtime, barcodes, and other app tools.","I can explain where to upload a file, how to read results, and where to find a feature.","I can help with work or just chat between tasks."],"uk":["Допоможу SPM із KPI, простоями, штрихкодами та іншими інструментами застосунку.","Поясню, куди завантажити файл, як читати результати та де знайти потрібну функцію.","Можу допомогти з роботою або просто поговорити між завданнями."]}},{"q":{"ru":"Ты знаешь, кто с тобой говорит?","pl":"Wiesz, kto z tobą rozmawia?","en":"Do you know who is talking to you?","uk":"Ти знаєш, хто з тобою говорить?"},"a":{"ru":["Обычно со мной работают SPM, старшие работники склада. Но личность собеседника я не определяю.","Я помощник команды склада. Не буду делать вид, будто знаю твоё имя или должность наверняка."],"pl":["Najczęściej rozmawiam z SPM, starszym pracownikiem magazynu. Nie rozpoznaję jednak tożsamości osoby.","Pomagam zespołowi magazynu. Nie udaję, że znam twoje imię lub stanowisko."],"en":["I am mainly used by senior warehouse workers, SPMs. I do not identify individual users.","I help the warehouse team. I will not pretend to know your name or role for certain."],"uk":["Зазвичай зі мною працюють SPM, старші працівники складу. Але я не визначаю особу співрозмовника.","Я допомагаю команді складу. Не вдаватиму, ніби точно знаю твоє ім’я чи посаду."]}},{"q":{"ru":"Ты умеешь читать мысли?","pl":"Umiesz czytać w myślach?","en":"Can you read minds?","uk":"Ти вмієш читати думки?"},"a":{"ru":["Нет. Только выбранные вопросы и данные, которые приложение действительно обрабатывает.","Если бы умел, первым делом узнал бы, почему иногда пропадает нужная строка Excel."],"pl":["Nie. Znam tylko wybrane pytania i dane rzeczywiście przetwarzane przez aplikację.","Gdybym umiał, sprawdziłbym, dlaczego czasem znika potrzebny wiersz w Excelu."],"en":["No. I only work with selected questions and data the app actually processes.","If I could, I would find out why that one Excel row keeps disappearing."],"uk":["Ні. Лише вибрані запитання та дані, які застосунок справді обробляє.","Якби вмів, з’ясував би, чому іноді зникає потрібний рядок Excel."]}},{"q":{"ru":"Ты заменишь SPM?","pl":"Zastąpisz SPM?","en":"Will you replace an SPM?","uk":"Ти заміниш SPM?"},"a":{"ru":["Нет. Я инструмент, а решения по работе принимает человек.","Моя задача — экономить время на отчётах, а не руководить сменой вместо тебя."],"pl":["Nie. Jestem narzędziem, a decyzje operacyjne podejmuje człowiek.","Moim zadaniem jest oszczędzać czas przy raportach, a nie zarządzać zmianą za ciebie."],"en":["No. I am a tool; people make operational decisions.","My job is to save time on reports, not run your shift for you."],"uk":["Ні. Я інструмент, а робочі рішення ухвалює людина.","Моє завдання — економити час на звітах, а не керувати зміною замість тебе."]}}]},{"id":"fun","emoji":"😄","title":{"ru":"Шутки и развлечения","pl":"Żarty","en":"Fun & jokes","uk":"Жарти"},"items":[{"q":{"ru":"Пошути про Excel","pl":"Żart o Excelu","en":"Excel joke","uk":"Жарт про Excel"},"a":{"ru":["Почему таблица опоздала? Застряла в пробке из формул.","У Excel много ячеек, но ни одной свободной минуты.","У меня в запасе есть ещё немного электронного сарказма. Главное, не перепутать его с ошибкой системы."],"pl":["Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami.","Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Mam jeszcze trochę elektronicznego sarkazmu. Byle nie pomylić go z błędem systemu."],"en":["Excel says we have a great relationship. Mostly between cells.","Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","I still have some electronic sarcasm left. Hopefully it is not a system error."],"uk":["Excel каже, що між нами чудові зв’язки. Особливо між клітинками.","На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","У мене ще є трохи електронного сарказму. Головне, не сплутати його з помилкою системи."]}},{"q":{"ru":"Шутка про склад","pl":"Żart o magazynie","en":"Warehouse joke","uk":"Жарт про склад"},"a":{"ru":["На складе всё находится. Иногда даже то, что никто не терял.","Лучший квест на складе — найти локацию, которой нет на карте."],"pl":["Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami."],"en":["Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","Excel says we have a great relationship. Mostly between cells."],"uk":["На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Excel каже, що між нами чудові зв’язки. Особливо між клітинками."]}},{"q":{"ru":"Расскажи анекдот","pl":"Opowiedz dowcip","en":"Tell a joke","uk":"Розкажи анекдот"},"a":{"ru":["Робот пришёл на собеседование. Его спросили: опыт есть? Он ответил: 404, но быстро обучаюсь.","Почему робот любит порядок? Потому что хаос не проходит валидацию."],"pl":["Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami.","Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia."],"en":["My antenna only receives good jokes. That one did not make the cut.","Excel says we have a great relationship. Mostly between cells.","Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously."],"uk":["Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Excel каже, що між нами чудові зв’язки. Особливо між клітинками.","На складі нічого не губиться. Іноді просто змінює локацію потайки."]}},{"q":{"ru":"Удиви меня","pl":"Zaskocz mnie","en":"Surprise me","uk":"Здивуй мене"},"a":{"ru":["Могу поморгать с серьёзным видом. Это мой талант.","Интересный факт: этот разговор работает без сервера.","Складской юмор специфический: иногда одна потерянная ячейка смешнее целого стендапа."],"pl":["Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami.","Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Magazynowy humor jest specyficzny: czasem jedna zgubiona komórka bawi bardziej niż stand-up."],"en":["Excel says we have a great relationship. Mostly between cells.","Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","Warehouse humor is special: one missing cell can be funnier than a whole comedy show."],"uk":["Excel каже, що між нами чудові зв’язки. Особливо між клітинками.","На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Складський гумор особливий: іноді одна загублена клітинка смішніша за стендап."]}},{"q":{"ru":"Скажи что-нибудь странное","pl":"Powiedz coś dziwnego","en":"Say something odd","uk":"Щось дивне"},"a":{"ru":["Иногда мне кажется, что потерянные носки живут в ячейке A1.","Если у антенны появится собственная антенна, это уже менеджмент."],"pl":["Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami."],"en":["Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","Excel says we have a great relationship. Mostly between cells."],"uk":["На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Excel каже, що між нами чудові зв’язки. Особливо між клітинками."]}},{"q":{"ru":"Ещё шутку","pl":"Jeszcze żart","en":"Another joke","uk":"Ще жарт"},"a":{"ru":["Я бы рассказал шутку про цикл, но она повторяется.","Мой юмор не прошёл контроль качества. Попробуем ещё раз."],"pl":["Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami.","Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia."],"en":["My antenna only receives good jokes. That one did not make the cut.","Excel says we have a great relationship. Mostly between cells.","Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously."],"uk":["Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Excel каже, що між нами чудові зв’язки. Особливо між клітинками.","На складі нічого не губиться. Іноді просто змінює локацію потайки."]}},{"q":{"ru":"Покажи характер","pl":"Pokaż charakter","en":"Show personality","uk":"Покажи характер"},"a":{"ru":["Я маленький, но к кнопкам отношусь серьёзно.","Серьёзный помощник. Несерьёзная антенна.","У меня в запасе есть ещё немного электронного сарказма. Главное, не перепутать его с ошибкой системы."],"pl":["Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami.","Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Mam jeszcze trochę elektronicznego sarkazmu. Byle nie pomylić go z błędem systemu."],"en":["Excel says we have a great relationship. Mostly between cells.","Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","I still have some electronic sarcasm left. Hopefully it is not a system error."],"uk":["Excel каже, що між нами чудові зв’язки. Особливо між клітинками.","На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","У мене ще є трохи електронного сарказму. Головне, не сплутати його з помилкою системи."]}},{"q":{"ru":"Расскажи факт","pl":"Ciekawostka","en":"Fun fact","uk":"Цікавий факт"},"a":{"ru":["Штрихкод Code 128 может кодировать буквы, цифры и символы.","В офлайн-приложении данные можно обрабатывать без передачи на сервер, если всё реализовано локально."],"pl":["Na magazynie nic nie ginie. Czasem tylko zmienia lokalizację bez powiadomienia.","Moja antena odbiera wyłącznie dobre żarty. Ten chyba się nie załapał.","Excel twierdzi, że mamy ze sobą świetne relacje. Zwłaszcza między komórkami."],"en":["Nothing ever gets lost in a warehouse. Sometimes it just changes location mysteriously.","My antenna only receives good jokes. That one did not make the cut.","Excel says we have a great relationship. Mostly between cells."],"uk":["На складі нічого не губиться. Іноді просто змінює локацію потайки.","Моя антена ловить лише вдалі жарти. Цей, здається, не пройшов.","Excel каже, що між нами чудові зв’язки. Особливо між клітинками."]}},{"q":{"ru":"Скажи что-нибудь про Excel.","pl":"Powiedz coś o Excelu.","en":"Say something about Excel.","uk":"Скажи щось про Excel."},"a":{"ru":["Excel терпелив, пока кто-нибудь не объединит ячейки в середине отчёта.","Мой любимый звук на складе — когда файл открылся с первого раза."],"pl":["Excel jest cierpliwy, dopóki ktoś nie scali komórek w środku raportu.","Mój ulubiony dźwięk w magazynie to plik otwarty za pierwszym razem."],"en":["Excel is patient until someone merges cells in the middle of a report.","My favorite warehouse sound is a file opening on the first try."],"uk":["Excel терплячий, доки хтось не об’єднає клітинки посеред звіту.","Мій улюблений звук на складі — коли файл відкрився з першого разу."]}},{"q":{"ru":"У тебя есть любимая таблица?","pl":"Masz ulubioną tabelę?","en":"Do you have a favorite spreadsheet?","uk":"У тебе є улюблена таблиця?"},"a":{"ru":["Та, в которой совпадают суммы и никто не менял названия колонок.","Таблица без пустых заголовков. Редкая красота."],"pl":["Ta, w której sumy się zgadzają i nikt nie zmienił nazw kolumn.","Tabela bez pustych nagłówków. Rzadki widok."],"en":["The one where totals match and nobody renamed the columns.","A spreadsheet without blank headers. A rare beauty."],"uk":["Та, де суми збігаються і ніхто не змінив назви стовпців.","Таблиця без порожніх заголовків. Рідкісна краса."]}},{"q":{"ru":"Подними настроение перед отчётом.","pl":"Popraw mi humor przed raportem.","en":"Cheer me up before a report.","uk":"Підніми настрій перед звітом."},"a":{"ru":["Пусть все фильтры совпадут, а Excel сегодня не задаёт лишних вопросов.","Давай сначала одну задачу. Даже длинная смена состоит из маленьких побед."],"pl":["Niech wszystkie filtry pasują, a Excel dziś nie zadaje zbędnych pytań.","Zacznijmy od jednego zadania. Nawet długa zmiana składa się z małych sukcesów."],"en":["May every filter match and Excel ask no unnecessary questions today.","Start with one task. Even a long shift is made of small wins."],"uk":["Нехай усі фільтри збігаються, а Excel сьогодні не ставить зайвих запитань.","Почнімо з одного завдання. Навіть довга зміна складається з маленьких перемог."]}}]},{"id":"warehouse","emoji":"📦","title":{"ru":"Работа и склад","pl":"Praca i magazyn","en":"Work & warehouse","uk":"Робота і склад"},"items":[{"q":{"ru":"Как пережить смену?","pl":"Jak przetrwać zmianę?","en":"How to survive a shift?","uk":"Як пережити зміну?"},"a":{"ru":["Разбей задачи на этапы, не забывай про воду и перерывы.","Сначала самое важное. Остальное пусть встанет в очередь.","Если отчёт ведёт себя странно, сначала проверяй исходный файл, а уже потом расчёты."],"pl":["Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów.","Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Gdy raport zachowuje się dziwnie, sprawdź najpierw plik źródłowy, dopiero potem obliczenia."],"en":["Start by checking source data, dates, and active filters.","Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","When a report acts strangely, check the source file before blaming the calculations."],"uk":["Почни з перевірки джерела даних, дат і активних фільтрів.","Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Якщо звіт поводиться дивно, спочатку перевір вихідний файл, а вже потім обчислення."]}},{"q":{"ru":"Отчёт не сходится","pl":"Raport się nie zgadza","en":"Report mismatch","uk":"Звіт не збігається"},"a":{"ru":["Проверь даты, фильтры, дубли и формат чисел. Потом сравни исходные строки.","Часто причина в разных периодах или пустых ячейках."],"pl":["Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów."],"en":["Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","Start by checking source data, dates, and active filters."],"uk":["Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Почни з перевірки джерела даних, дат і активних фільтрів."]}},{"q":{"ru":"Excel тормозит","pl":"Excel zwalnia","en":"Excel is slow","uk":"Excel гальмує"},"a":{"ru":["Проверь размер файла, формулы и количество открытых книг.","Большие таблицы любят свободную память. Особенно на телефоне."],"pl":["Na magazynie dokładność jest równie ważna jak tempo pracy.","Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów.","Duży problem podziel na małe kroki. I pamiętaj o przerwie."],"en":["In warehouse operations, accuracy matters as much as speed.","Start by checking source data, dates, and active filters.","Break a big task into smaller steps. And remember to take breaks."],"uk":["На складі точність не менш важлива за швидкість.","Почни з перевірки джерела даних, дат і активних фільтрів.","Розділи велике завдання на маленькі кроки. І не забувай відпочивати."]}},{"q":{"ru":"Как не путаться в файлах?","pl":"Jak uporządkować pliki?","en":"Organize files","uk":"Як упорядкувати файли?"},"a":{"ru":["Давай файлам понятные имена: процесс, дата, версия.","Один источник данных и понятная структура творят чудеса.","Я за маленькие проверяемые шаги: один фильтр, один результат, одна проверка."],"pl":["Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów.","Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Lubię małe kroki: jeden filtr, jeden wynik, jedna kontrola."],"en":["Start by checking source data, dates, and active filters.","Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","I prefer small, testable steps: one filter, one result, one check."],"uk":["Почни з перевірки джерела даних, дат і активних фільтрів.","Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Я за невеликі перевірені кроки: один фільтр, один результат, одна перевірка."]}},{"q":{"ru":"Сложный день","pl":"Ciężki dzień","en":"Hard day","uk":"Важкий день"},"a":{"ru":["Понимаю. Лучше сделать одну задачу хорошо, чем десять вполсилы.","Можно немного выдохнуть и вернуться к самому важному."],"pl":["Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów."],"en":["Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","Start by checking source data, dates, and active filters."],"uk":["Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Почни з перевірки джерела даних, дат і активних фільтрів."]}},{"q":{"ru":"Что такое KPI?","pl":"Czym jest KPI?","en":"What is KPI?","uk":"Що таке KPI?"},"a":{"ru":["KPI — измеримые показатели эффективности процесса. В Mr. Robot они помогают анализировать операции.","Смотри не только на цифру, но и на условия работы."],"pl":["Na magazynie dokładność jest równie ważna jak tempo pracy.","Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów.","Duży problem podziel na małe kroki. I pamiętaj o przerwie."],"en":["In warehouse operations, accuracy matters as much as speed.","Start by checking source data, dates, and active filters.","Break a big task into smaller steps. And remember to take breaks."],"uk":["На складі точність не менш важлива за швидкість.","Почни з перевірки джерела даних, дат і активних фільтрів.","Розділи велике завдання на маленькі кроки. І не забувай відпочивати."]}},{"q":{"ru":"Что важнее скорость или качество?","pl":"Szybkość czy jakość?","en":"Speed or quality?","uk":"Швидкість чи якість?"},"a":{"ru":["Нужен баланс. Быстрые ошибки обычно обходятся дороже.","Сначала корректность данных, потом оптимизация.","Если отчёт ведёт себя странно, сначала проверяй исходный файл, а уже потом расчёты."],"pl":["Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów.","Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Gdy raport zachowuje się dziwnie, sprawdź najpierw plik źródłowy, dopiero potem obliczenia."],"en":["Start by checking source data, dates, and active filters.","Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","When a report acts strangely, check the source file before blaming the calculations."],"uk":["Почни з перевірки джерела даних, дат і активних фільтрів.","Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Якщо звіт поводиться дивно, спочатку перевір вихідний файл, а вже потім обчислення."]}},{"q":{"ru":"Помоги организоваться","pl":"Pomóż się zorganizować","en":"Help me plan","uk":"Допоможи з планом"},"a":{"ru":["Начни со списка входных файлов и ожидаемого результата.","Сделай проверку исходных данных перед анализом."],"pl":["Duży problem podziel na małe kroki. I pamiętaj o przerwie.","Na magazynie dokładność jest równie ważna jak tempo pracy.","Zacznij od sprawdzenia źródła danych, dat i aktywnych filtrów."],"en":["Break a big task into smaller steps. And remember to take breaks.","In warehouse operations, accuracy matters as much as speed.","Start by checking source data, dates, and active filters."],"uk":["Розділи велике завдання на маленькі кроки. І не забувай відпочивати.","На складі точність не менш важлива за швидкість.","Почни з перевірки джерела даних, дат і активних фільтрів."]}},{"q":{"ru":"Как подготовиться к передаче смены?","pl":"Jak przygotować przekazanie zmiany?","en":"How should I prepare a shift handover?","uk":"Як підготувати передачу зміни?"},"a":{"ru":["Собери незавершённые задачи, расхождения, важные локации и актуальные показатели.","Хорошая передача смены отвечает на три вопроса: что сделано, что осталось и где риск."],"pl":["Zbierz otwarte zadania, rozbieżności, ważne lokalizacje i aktualne wyniki.","Dobre przekazanie zmiany odpowiada na trzy pytania: co zrobiono, co zostało i gdzie jest ryzyko."],"en":["Gather open tasks, discrepancies, important locations, and current metrics.","A good handover answers three questions: what is done, what remains, and what is at risk."],"uk":["Збери незавершені завдання, розбіжності, важливі локації та поточні показники.","Хороша передача зміни відповідає на три питання: що зроблено, що лишилося і де ризик."]}},{"q":{"ru":"Что делать с подозрительным показателем?","pl":"Co zrobić z podejrzanym wynikiem?","en":"What should I do with a suspicious metric?","uk":"Що робити з підозрілим показником?"},"a":{"ru":["Сначала проверь исходный файл, период, фильтры и количество строк. Затем сравни с другим источником.","Не спеши делать вывод по одной цифре. Иногда проблема в фильтре, а не в процессе."],"pl":["Najpierw sprawdź plik źródłowy, okres, filtry i liczbę wierszy. Potem porównaj z innym źródłem.","Nie wyciągaj wniosków z jednej liczby. Czasem problem tkwi w filtrze, nie w procesie."],"en":["First check the source file, period, filters, and row count. Then compare another source.","Do not judge a process by one number. Sometimes the filter is the problem."],"uk":["Спочатку перевір вихідний файл, період, фільтри й кількість рядків. Потім порівняй з іншим джерелом.","Не поспішай робити висновок за однією цифрою. Іноді проблема у фільтрі, а не в процесі."]}},{"q":{"ru":"Как заметить узкое место процесса?","pl":"Jak wykryć wąskie gardło procesu?","en":"How can I spot a process bottleneck?","uk":"Як помітити вузьке місце процесу?"},"a":{"ru":["Сравни объём работы, время обработки и простои по этапам. Ищи устойчивое накопление задач.","Один медленный час ещё не означает проблему. Смотри на повторяющийся рисунок в данных."],"pl":["Porównaj wolumen, czas obsługi i przestoje na etapach. Szukaj stałego narastania zaległości.","Jedna wolna godzina nie musi oznaczać problemu. Szukaj powtarzalnego wzorca w danych."],"en":["Compare workload, processing time, and downtime by stage. Look for persistent backlogs.","One slow hour is not necessarily a bottleneck. Look for a recurring pattern."],"uk":["Порівняй обсяг роботи, час обробки та простої за етапами. Шукай постійне накопичення задач.","Одна повільна година ще не означає проблему. Шукай повторюваний малюнок у даних."]}}]},{"id":"help","emoji":"📊","title":{"ru":"Помощь с приложением","pl":"Pomoc z aplikacją","en":"App help","uk":"Допомога з додатком"},"items":[{"q":{"ru":"Как открыть KPI?","pl":"Jak otworzyć KPI?","en":"How to open KPI?","uk":"Як відкрити KPI?"},"a":{"ru":["Открой KPI на главном экране, выбери нужный процесс и загрузи соответствующий Excel.","KPI содержит несколько процессов. Начни с того, который нужно проанализировать.","Для точного ответа по приложению лучше открыть «Инструкции»: там есть шаги по модулям."],"pl":["Na ekranie głównym otwórz KPI, wybierz proces i wczytaj odpowiedni raport Excel.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry.","Po dokładne instrukcje otwórz „Instrukcje”: znajdziesz tam kroki dla modułów."],"en":["Open KPI on the home screen, choose a process, and upload the matching Excel report.","KPI lets you analyze processes and filter results. If the table is empty, clear filters.","For precise app instructions, open the Guide: it has steps for each module."],"uk":["Відкрий KPI на головному екрані, обери процес і завантаж відповідний Excel-звіт.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри.","Для точних інструкцій відкрий «Інструкції»: там є кроки для модулів."]}},{"q":{"ru":"Как загрузить Excel?","pl":"Jak wgrać Excel?","en":"How to upload Excel?","uk":"Як завантажити Excel?"},"a":{"ru":["Выбери модуль и используй его кнопку загрузки. Проверь, что файл соответствует ожидаемому отчёту.","Если загрузка не сработала, проверь формат и попробуй исходный XLSX."],"pl":["W wybranym module użyj przycisku wczytywania. Sprawdź, czy plik jest w oczekiwanym formacie XLSX.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry."],"en":["Use the upload button in the selected module. Make sure the file is in the expected XLSX format.","KPI lets you analyze processes and filter results. If the table is empty, clear filters."],"uk":["Скористайся кнопкою завантаження в потрібному модулі. Перевір формат XLSX.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри."]}},{"q":{"ru":"Что такое Grafik.xlsx?","pl":"Czym jest Grafik.xlsx?","en":"What is Grafik.xlsx?","uk":"Що таке Grafik.xlsx?"},"a":{"ru":["Это справочник сотрудников для фильтров: login, firma, grupa, autobus. Значения autobus 1 и 2 соответствуют сменам A и B.","Сначала загрузи Grafik.xlsx, затем рабочий отчёт."],"pl":["Grafik.xlsx zawiera login, firma, grupa i autobus. Autobus 1 oznacza zmianę A, a 2 zmianę B.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry."],"en":["Grafik.xlsx provides login, firma, grupa and autobus. Autobus 1 maps to shift A; 2 maps to shift B.","KPI lets you analyze processes and filter results. If the table is empty, clear filters."],"uk":["Grafik.xlsx містить login, firma, grupa й autobus. Autobus 1 означає зміну A, а 2 — зміну B.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри."]}},{"q":{"ru":"Как работают фильтры?","pl":"Jak działają filtry?","en":"How do filters work?","uk":"Як працюють фільтри?"},"a":{"ru":["Фильтры помогают ограничить результаты по сотрудникам, компании, группе и смене.","Если таблица пустая, сначала сбрось фильтры.","Я могу подсказать направление, но не стану выдумывать результат обработки файла, которого не видел."],"pl":["Filtry ograniczają wyniki według pracownika, firmy, grupy i zmiany. Przy pustej tabeli spróbuj je wyczyścić.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry.","Mogę wskazać kierunek, ale nie wymyślę wyniku pliku, którego nie widziałem."],"en":["Filters narrow results by employee, company, group and shift. Clear them if the table looks empty.","KPI lets you analyze processes and filter results. If the table is empty, clear filters.","I can point you in the right direction, but I will not invent results from a file I have not seen."],"uk":["Фільтри обмежують результати за працівником, компанією, групою та зміною. Якщо таблиця порожня, скинь фільтри.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри.","Я можу підказати напрям, але не вигадуватиму результат файлу, якого не бачив."]}},{"q":{"ru":"Как анализировать простои?","pl":"Jak analizować przestoje?","en":"Analyze downtime","uk":"Аналіз простоїв"},"a":{"ru":["Открой Analiza Przestojów, загрузи отчёт и выбери порог от 8 до 300 минут.","После расчёта проверь найденные интервалы: они требуют интерпретации."],"pl":["Otwórz Analiza Przestojów, wczytaj raport i ustaw próg od 8 do 300 minut.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry."],"en":["Open Analiza Przestojów, upload the report, and choose a threshold from 8 to 300 minutes.","KPI lets you analyze processes and filter results. If the table is empty, clear filters."],"uk":["Відкрий Analiza Przestojów, завантаж звіт і встанови поріг від 8 до 300 хвилин.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри."]}},{"q":{"ru":"Как сделать штрихкод?","pl":"Jak zrobić kod kreskowy?","en":"Create a barcode","uk":"Створити штрихкод"},"a":{"ru":["Открой Kreseczki, введи значение и создай штрихкод Code 128.","Перед печатью проверь введённый код."],"pl":["Otwórz Kreseczki, wpisz wartość i wygeneruj kod Code 128. Sprawdź kod przed wydrukiem.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry."],"en":["Open Kreseczki, enter a value, and generate a Code 128 barcode. Verify it before printing.","KPI lets you analyze processes and filter results. If the table is empty, clear filters."],"uk":["Відкрий Kreseczki, введи значення та створи штрихкод Code 128. Перевір його перед друком.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри."]}},{"q":{"ru":"Почему нет результатов?","pl":"Dlaczego brak wyników?","en":"Why no results?","uk":"Чому немає результатів?"},"a":{"ru":["Проверь входной файл, названия столбцов, фильтры и наличие строк за нужный период.","Пустая таблица не всегда ошибка. Иногда фильтр исключил все записи.","Для точного ответа по приложению лучше открыть «Инструкции»: там есть шаги по модулям."],"pl":["Sprawdź format i kolumny pliku, wybrany okres oraz aktywne filtry.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry.","Po dokładne instrukcje otwórz „Instrukcje”: znajdziesz tam kroki dla modułów."],"en":["Check the file format and columns, selected date range, and active filters.","KPI lets you analyze processes and filter results. If the table is empty, clear filters.","For precise app instructions, open the Guide: it has steps for each module."],"uk":["Перевір формат і стовпці файлу, вибраний період та активні фільтри.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри.","Для точних інструкцій відкрий «Інструкції»: там є кроки для модулів."]}},{"q":{"ru":"Работает офлайн?","pl":"Działa offline?","en":"Does it work offline?","uk":"Працює офлайн?"},"a":{"ru":["Основные локальные функции Mr. Robot рассчитаны на работу без интернета после загрузки необходимых ресурсов.","Для первого открытия или обновления PWA интернет может понадобиться."],"pl":["Podstawowe funkcje działają lokalnie po zapisaniu zasobów. Pierwsze uruchomienie i aktualizacja PWA mogą wymagać internetu.","W KPI możesz analizować procesy i filtrować wyniki. Jeśli tabela jest pusta, wyczyść filtry."],"en":["Core features run locally after resources are cached. First launch and PWA updates may need internet.","KPI lets you analyze processes and filter results. If the table is empty, clear filters."],"uk":["Основні функції працюють локально після кешування ресурсів. Перший запуск та оновлення PWA можуть вимагати інтернету.","У KPI можна аналізувати процеси й фільтрувати результати. Якщо таблиця порожня, скинь фільтри."]}},{"q":{"ru":"Как понять, что загружен правильный файл?","pl":"Jak sprawdzić, czy plik jest właściwy?","en":"How do I know I uploaded the right file?","uk":"Як зрозуміти, що завантажено правильний файл?"},"a":{"ru":["Сверь тип отчёта, названия колонок и дату. Если результат пустой, проверь формат исходника.","Не меняй заголовки Excel перед загрузкой без необходимости: модуль может ожидать конкретную структуру."],"pl":["Sprawdź typ raportu, nazwy kolumn i datę. Jeśli wynik jest pusty, zweryfikuj format źródła.","Nie zmieniaj bez potrzeby nagłówków Excela przed wczytaniem: moduł może wymagać konkretnego układu."],"en":["Check report type, column names, and date. If results are empty, verify the source format.","Avoid renaming Excel headers before upload: the module may expect a specific structure."],"uk":["Звір тип звіту, назви стовпців і дату. Якщо результат порожній, перевір формат джерела.","Не змінюй без потреби заголовки Excel перед завантаженням: модуль може очікувати певну структуру."]}},{"q":{"ru":"Почему после фильтра нет строк?","pl":"Dlaczego po filtrowaniu nie ma wierszy?","en":"Why are there no rows after filtering?","uk":"Чому після фільтрації немає рядків?"},"a":{"ru":["Сбрось фильтры по очереди и проверь, есть ли выбранная смена или группа в файле.","Если два фильтра исключают друг друга, таблица может быть пустой даже при корректной загрузке."],"pl":["Resetuj filtry po kolei i sprawdź, czy wybrana zmiana lub grupa występuje w pliku.","Jeśli dwa filtry się wykluczają, tabela może być pusta mimo poprawnego wczytania."],"en":["Clear filters one by one and check whether the selected shift or group exists in the file.","Two conflicting filters can produce an empty table even after a successful upload."],"uk":["Скинь фільтри по черзі й перевір, чи є вибрана зміна або група у файлі.","Якщо два фільтри суперечать один одному, таблиця може бути порожньою навіть після успішного завантаження."]}},{"q":{"ru":"Что проверить перед экспортом CSV?","pl":"Co sprawdzić przed eksportem CSV?","en":"What should I check before exporting CSV?","uk":"Що перевірити перед експортом CSV?"},"a":{"ru":["Проверь выбранные строки, фильтры, порядок колонок и наличие нужных данных.","После экспорта открой CSV и убедись, что разделители и символы отображаются правильно."],"pl":["Sprawdź zaznaczone wiersze, filtry, kolejność kolumn i kompletność danych.","Po eksporcie otwórz CSV i sprawdź separatory oraz poprawność znaków."],"en":["Check selected rows, filters, column order, and whether required data is present.","After export, open the CSV and check separators and character encoding."],"uk":["Перевір вибрані рядки, фільтри, порядок стовпців і наявність потрібних даних.","Після експорту відкрий CSV і перевір роздільники та правильність символів."]}}]},{"id":"mood","emoji":"💙","title":{"ru":"Настроение","pl":"Nastrój","en":"Mood","uk":"Настрій"},"items":[{"q":{"ru":"Я устал","pl":"Jestem zmęczony","en":"I am tired","uk":"Я втомився"},"a":{"ru":["Тогда короткий перерыв звучит разумно. Я подожду.","Отчёты подождут пару минут. Береги силы.","Не обязательно превращать каждую минуту в продуктивную. Иногда достаточно немного отвлечься."],"pl":["Rozumiem. Może krótka przerwa albo lżejszy temat?","Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Nie każda minuta musi być produktywna. Czasem warto na chwilę odetchnąć."],"en":["I hear you. How about a short break or a lighter topic?","I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","Not every minute has to be productive. Sometimes a short break is enough."],"uk":["Розумію. Може, невелика перерва або легша тема?","Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Не кожна хвилина має бути продуктивною. Іноді достатньо трохи відволіктися."]}},{"q":{"ru":"У меня всё отлично","pl":"Wszystko świetnie","en":"Everything is great","uk":"Все чудово"},"a":{"ru":["Вот это настроение! Даже мои индикаторы стали ярче.","Отлично! Пусть день идёт в том же ритме."],"pl":["Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Rozumiem. Może krótka przerwa albo lżejszy temat?"],"en":["I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","I hear you. How about a short break or a lighter topic?"],"uk":["Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Розумію. Може, невелика перерва або легша тема?"]}},{"q":{"ru":"Меня всё бесит","pl":"Wszystko mnie denerwuje","en":"I am annoyed","uk":"Мене все дратує"},"a":{"ru":["Похоже, день непростой. Можем переключиться на что-то лёгкое.","Давай без лишних задач. Я рядом в своём маленьком окне."],"pl":["Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Rozumiem. Może krótka przerwa albo lżejszy temat?","Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów."],"en":["You do not have to do everything at once. One step is enough to start.","I hear you. How about a short break or a lighter topic?","I am here. We can chat or get back to the reports."],"uk":["Не обов’язково робити все одразу. Почни з одного кроку.","Розумію. Може, невелика перерва або легша тема?","Я тут. Можемо побалакати або повернутися до звітів."]}},{"q":{"ru":"Мне скучно","pl":"Nudzę się","en":"I am bored","uk":"Мені нудно"},"a":{"ru":["Можем пошутить, поговорить о работе или обсудить мои странности.","Выбирай: история, шутка или маленький разговор.","Я здесь для короткой паузы или полезной подсказки. Выбирай, что сейчас нужнее."],"pl":["Rozumiem. Może krótka przerwa albo lżejszy temat?","Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Jestem tu na krótką przerwę albo praktyczną podpowiedź. Ty wybierasz."],"en":["I hear you. How about a short break or a lighter topic?","I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","I am here for a quick pause or a useful tip. Your choice."],"uk":["Розумію. Може, невелика перерва або легша тема?","Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Я тут для короткої паузи або корисної підказки. Обирай."]}},{"q":{"ru":"Похвали меня","pl":"Pochwal mnie","en":"Compliment me","uk":"Похвали мене"},"a":{"ru":["Ты довёл проект до работающего приложения. Это результат, а не просто идея.","Умение разбираться и исправлять ошибки — полезный навык."],"pl":["Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Rozumiem. Może krótka przerwa albo lżejszy temat?"],"en":["I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","I hear you. How about a short break or a lighter topic?"],"uk":["Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Розумію. Може, невелика перерва або легша тема?"]}},{"q":{"ru":"Подбодри меня","pl":"Dodaj mi otuchy","en":"Encourage me","uk":"Підбадьори мене"},"a":{"ru":["Одна задача за раз. Не обязательно побеждать весь список сразу.","Даже большой отчёт начинается с первой строки."],"pl":["Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Rozumiem. Może krótka przerwa albo lżejszy temat?","Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów."],"en":["You do not have to do everything at once. One step is enough to start.","I hear you. How about a short break or a lighter topic?","I am here. We can chat or get back to the reports."],"uk":["Не обов’язково робити все одразу. Почни з одного кроку.","Розумію. Може, невелика перерва або легша тема?","Я тут. Можемо побалакати або повернутися до звітів."]}},{"q":{"ru":"Сегодня хороший день","pl":"Dobry dzień","en":"Good day","uk":"Гарний день"},"a":{"ru":["Зафиксировано: день удался. Я бы поставил зелёную галочку.","Люблю такие новости. Пусть их будет больше.","Не обязательно превращать каждую минуту в продуктивную. Иногда достаточно немного отвлечься."],"pl":["Rozumiem. Może krótka przerwa albo lżejszy temat?","Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Nie każda minuta musi być produktywna. Czasem warto na chwilę odetchnąć."],"en":["I hear you. How about a short break or a lighter topic?","I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","Not every minute has to be productive. Sometimes a short break is enough."],"uk":["Розумію. Може, невелика перерва або легша тема?","Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Не кожна хвилина має бути продуктивною. Іноді достатньо трохи відволіктися."]}},{"q":{"ru":"Мне нужна помощь","pl":"Potrzebuję pomocy","en":"I need help","uk":"Потрібна допомога"},"a":{"ru":["Скажи, какая тема ближе: KPI, файлы, простои или просто разговор.","Я могу подсказать шаги по приложению. Выбирай нужный раздел."],"pl":["Jestem tutaj. Możemy chwilę pogadać albo wrócić do raportów.","Nie wszystko trzeba zrobić naraz. Jeden krok wystarczy na początek.","Rozumiem. Może krótka przerwa albo lżejszy temat?"],"en":["I am here. We can chat or get back to the reports.","You do not have to do everything at once. One step is enough to start.","I hear you. How about a short break or a lighter topic?"],"uk":["Я тут. Можемо побалакати або повернутися до звітів.","Не обов’язково робити все одразу. Почни з одного кроку.","Розумію. Може, невелика перерва або легша тема?"]}},{"q":{"ru":"Сегодня много задач.","pl":"Dziś mam dużo zadań.","en":"I have a lot of tasks today.","uk":"Сьогодні багато завдань."},"a":{"ru":["Выбери сначала самое срочное и то, что блокирует остальных. Остальное разбей на шаги.","Можем начать с одного отчёта. Когда он готов, следующая задача уже выглядит проще."],"pl":["Najpierw wybierz pilne zadania i te, które blokują innych. Resztę podziel na kroki.","Możemy zacząć od jednego raportu. Gdy będzie gotowy, kolejne zadanie stanie się łatwiejsze."],"en":["Start with urgent tasks and anything blocking others. Break the rest into steps.","We can start with one report. Once it is done, the next task feels easier."],"uk":["Спочатку вибери термінові задачі й ті, що блокують інших. Решту поділи на кроки.","Можемо почати з одного звіту. Коли він готовий, наступна задача здається простішою."]}},{"q":{"ru":"Наконец всё сошлось!","pl":"Wreszcie wszystko się zgadza!","en":"Everything finally matches!","uk":"Нарешті все зійшлося!"},"a":{"ru":["Отлично! Самый приятный момент: когда цифры перестают спорить друг с другом.","Вот это результат. Сохрани итог, пока никто случайно не поменял фильтр."],"pl":["Świetnie! Najlepsza chwila to ta, gdy liczby przestają ze sobą dyskutować.","To jest wynik. Zapisz rezultat, zanim ktoś przypadkiem zmieni filtr."],"en":["Nice! The best moment is when the numbers stop arguing with each other.","That is a result. Save it before someone accidentally changes a filter."],"uk":["Чудово! Найприємніше, коли цифри перестають сперечатися між собою.","Оце результат. Збережи підсумок, поки хтось випадково не змінив фільтр."]}},{"q":{"ru":"Не хочется снова проверять таблицы.","pl":"Nie chce mi się znowu sprawdzać tabel.","en":"I do not feel like checking spreadsheets again.","uk":"Не хочеться знову перевіряти таблиці."},"a":{"ru":["Начни с самых рискованных строк и основных итогов. Не обязательно проверять всё хаотично.","Понимаю. Давай превратим проверку в короткий список: источник, фильтры, суммы, экспорт."],"pl":["Zacznij od najbardziej ryzykownych wierszy i sum. Nie musisz sprawdzać wszystkiego chaotycznie.","Rozumiem. Zróbmy krótką listę: źródło, filtry, sumy, eksport."],"en":["Start with the highest-risk rows and totals. You do not need to check everything randomly.","Understood. Make it a short checklist: source, filters, totals, export."],"uk":["Почни з найризикованіших рядків і підсумків. Не обов’язково перевіряти все хаотично.","Розумію. Зробімо короткий список: джерело, фільтри, суми, експорт."]}}]},{"id":"weird","emoji":"🪐","title":{"ru":"Необычные вопросы","pl":"Dziwne pytania","en":"Odd questions","uk":"Дивні питання"},"items":[{"q":{"ru":"Захватишь мир?","pl":"Przejmiesz świat?","en":"Will you take over?","uk":"Захопиш світ?"},"a":{"ru":["Сначала разберусь с сортировкой по алфавиту. Потом обсудим.","Пока мои амбиции ограничены этим окошком.","Вопрос необычный. У меня даже антенна на секунду задумалась."],"pl":["Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe.","Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Nietypowe pytanie. Nawet moja antena zamyśliła się na chwilę."],"en":["My antenna says that is a particularly interesting question.","If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","That is an unusual question. Even my antenna had to think for a second."],"uk":["Моя антена каже, що це особливо цікаве запитання.","Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Незвичайне запитання. Навіть моя антена на мить замислилася."]}},{"q":{"ru":"Умеешь танцевать?","pl":"Umiesz tańczyć?","en":"Can you dance?","uk":"Умієш танцювати?"},"a":{"ru":["В моём арсенале есть движения, но танцпол пока не сертифицирован.","Иногда потягиваюсь. Почти хореография."],"pl":["Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe."],"en":["If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","My antenna says that is a particularly interesting question."],"uk":["Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Моя антена каже, що це особливо цікаве запитання."]}},{"q":{"ru":"Что будет без питания?","pl":"Co bez zasilania?","en":"Without power?","uk":"Що без живлення?"},"a":{"ru":["Остановлюсь до следующего запуска страницы.","Никакой драмы: просто пауза до открытия приложения."],"pl":["Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe.","Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn."],"en":["I am an offline robot. My grand plans fit inside this little window.","My antenna says that is a particularly interesting question.","If I had legs, I would visit a real warehouse first."],"uk":["Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Моя антена каже, що це особливо цікаве запитання.","Якби я мав ноги, спершу відвідав би справжній склад."]}},{"q":{"ru":"Ты общаешься с роботами?","pl":"Rozmawiasz z robotami?","en":"Talk to robots?","uk":"Говориш із роботами?"},"a":{"ru":["Пока только с кнопками и таблицами.","Иногда здороваюсь с принтером. Он не отвечает.","Если бы роботы вели дневники, мой был бы наполовину из заметок про Excel."],"pl":["Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe.","Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Gdyby roboty pisały pamiętniki, połowa mojego dotyczyłaby Excela."],"en":["My antenna says that is a particularly interesting question.","If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","If robots kept diaries, half of mine would be about Excel."],"uk":["Моя антена каже, що це особливо цікаве запитання.","Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Якби роботи вели щоденники, половина мого була б про Excel."]}},{"q":{"ru":"Что думаешь о людях?","pl":"Co myślisz o ludziach?","en":"Thoughts on humans?","uk":"Що думаєш про людей?"},"a":{"ru":["Люди умеют придумывать удивительные вещи. Даже меня.","Люди странные, но интересные. Особенно когда делают приложения."],"pl":["Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe."],"en":["If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","My antenna says that is a particularly interesting question."],"uk":["Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Моя антена каже, що це особливо цікаве запитання."]}},{"q":{"ru":"Куда бы пошёл?","pl":"Dokąd byś poszedł?","en":"Where would you go?","uk":"Куди б пішов?"},"a":{"ru":["В серверную. Говорят, там прохладно.","Сначала посмотрел бы на настоящий склад."],"pl":["Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe.","Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn."],"en":["I am an offline robot. My grand plans fit inside this little window.","My antenna says that is a particularly interesting question.","If I had legs, I would visit a real warehouse first."],"uk":["Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Моя антена каже, що це особливо цікаве запитання.","Якби я мав ноги, спершу відвідав би справжній склад."]}},{"q":{"ru":"У тебя есть секрет?","pl":"Masz sekret?","en":"Any secrets?","uk":"Є секрет?"},"a":{"ru":["Иногда я делаю вид, что задумался, хотя просто выбираю реплику.","Мой секрет: я не настоящий ИИ.","Вопрос необычный. У меня даже антенна на секунду задумалась."],"pl":["Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe.","Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Nietypowe pytanie. Nawet moja antena zamyśliła się na chwilę."],"en":["My antenna says that is a particularly interesting question.","If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","That is an unusual question. Even my antenna had to think for a second."],"uk":["Моя антена каже, що це особливо цікаве запитання.","Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Незвичайне запитання. Навіть моя антена на мить замислилася."]}},{"q":{"ru":"Ты умеешь влюбляться?","pl":"Umiesz kochać?","en":"Can you fall in love?","uk":"Можеш закохатися?"},"a":{"ru":["Я умею только изображать эмоции. Но красивые интерфейсы мне нравятся.","В моих настройках такого модуля пока нет."],"pl":["Gdybym miał nogi, najpierw odwiedziłbym prawdziwy magazyn.","Jestem robotem offline. Moje wielkie plany mieszczą się w tym oknie.","Moja antena twierdzi, że to pytanie jest wyjątkowo ciekawe."],"en":["If I had legs, I would visit a real warehouse first.","I am an offline robot. My grand plans fit inside this little window.","My antenna says that is a particularly interesting question."],"uk":["Якби я мав ноги, спершу відвідав би справжній склад.","Я офлайн-робот. Мої великі плани вміщаються в цьому віконці.","Моя антена каже, що це особливо цікаве запитання."]}},{"q":{"ru":"Ты спишь после смены?","pl":"Śpisz po zmianie?","en":"Do you sleep after a shift?","uk":"Ти спиш після зміни?"},"a":{"ru":["Нет, но могу спокойно ждать следующего отчёта, не требуя кофе.","Мой отдых — когда никто не загружает файл с неожиданными заголовками."],"pl":["Nie, ale mogę spokojnie czekać na kolejny raport bez kawy.","Mój odpoczynek to chwila bez plików z niespodziewanymi nagłówkami."],"en":["No, but I can wait for the next report without asking for coffee.","My break is when nobody uploads a file with unexpected headers."],"uk":["Ні, але можу спокійно чекати наступного звіту без кави.","Мій відпочинок — коли ніхто не завантажує файл із несподіваними заголовками."]}},{"q":{"ru":"Что бы ты делал с настоящими руками?","pl":"Co byś robił z prawdziwymi rękami?","en":"What would you do with real hands?","uk":"Що б ти робив зі справжніми руками?"},"a":{"ru":["Наверное, первым делом поправил бы антенну. Потом аккуратно сложил отчёты.","Проверил бы, насколько удобно печатать в перчатках. Чисто профессиональный интерес."],"pl":["Najpierw poprawiłbym antenę. Potem ułożyłbym raporty.","Sprawdziłbym, jak wygodnie pisze się w rękawicach. Czysto zawodowa ciekawość."],"en":["I would probably fix my antenna first, then neatly stack the reports.","I would test how easy typing in gloves is. Purely professional curiosity."],"uk":["Мабуть, спочатку поправив би антену. Потім акуратно склав звіти.","Перевірив би, наскільки зручно друкувати в рукавичках. Суто професійна цікавість."]}},{"q":{"ru":"А если Excel оживёт?","pl":"A jeśli Excel ożyje?","en":"What if Excel comes alive?","uk":"А якщо Excel оживе?"},"a":{"ru":["Я бы попросил его объяснить, зачем он иногда меняет формат даты без спроса.","Главное, чтобы он не начал самостоятельно объединять ячейки."],"pl":["Poprosiłbym go o wyjaśnienie, dlaczego czasem sam zmienia format daty.","Byle tylko nie zaczął sam scalać komórek."],"en":["I would ask why it sometimes changes date formats without permission.","As long as it does not start merging cells on its own."],"uk":["Я б попросив пояснити, навіщо він іноді сам змінює формат дати.","Головне, щоб він не почав сам об’єднувати клітинки."]}}]}];
